/* prog22_snake_camel_convert.c
 *
 * Reimplementation of the original binary's observable behaviour.
 * The program converts strings between snake_case and camelCase.
 *
 *   prog22_snake_camel_convert MODE INPUT
 *
 *   MODE  : "to_camel" or "to_snake"
 *   INPUT : string to be converted
 *
 *   Prints the converted string on stdout.
 *   Prints "USAGE"   if the argument count is wrong.
 *   Prints "INVALID_MODE" if MODE is not recognised.
 *
 * The original binary used a static buffer of 1024 bytes for the output.
 */

#include <stdio.h>
#include <string.h>
#include <ctype.h>

#define OUT_BUF_SIZE 1024

static char out_buf[OUT_BUF_SIZE];

/* Convert snake_case to camelCase.
 * Underscores are removed and the following alphabetic character is
 * capitalised.  All other characters are copied unchanged.
 */
static void to_camel(const char *src)
{
    size_t out = 0;
    int capitalize = 0;               /* flag set after '_' */

    while (*src && out + 1 < OUT_BUF_SIZE) {
        if (*src == '_') {
            capitalize = 1;           /* next character should be upper */
        } else {
            char ch = *src;
            if (capitalize && islower((unsigned char)ch))
                ch = (char)toupper((unsigned char)ch);
            out_buf[out++] = ch;
            capitalize = 0;
        }
        ++src;
    }
    out_buf[out] = '\0';
}

/* Convert camelCase to snake_case.
 * Upper‑case letters become '_' + lower‑case letter (except before the
 * first character).  All other characters are copied unchanged.
 */
static void to_snake(const char *src)
{
    size_t out = 0;
    int first = 1;                    /* true while we are at the first char */

    while (*src && out + 1 < OUT_BUF_SIZE) {
        unsigned char ch = (unsigned char)*src;

        if (isupper(ch)) {
            if (!first) {
                out_buf[out++] = '_';
            }
            out_buf[out++] = (char)tolower(ch);
        } else {
            out_buf[out++] = (char)ch;
        }

        first = 0;
        ++src;
    }
    out_buf[out] = '\0';
}

int main(int argc, char **argv)
{
    if (argc < 3) {
        puts("USAGE");
        return 0;
    }

    const char *mode = argv[1];
    const char *input = argv[2];

    if (strcmp(mode, "to_camel") == 0) {
        to_camel(input);
        puts(out_buf);
    } else if (strcmp(mode, "to_snake") == 0) {
        to_snake(input);
        puts(out_buf);
    } else {
        puts("INVALID_MODE");
    }

    return 0;
}
